import java.util.*;

class Solution {
    // 方法一：排序法 — 代码最简，面试首选
    public List<List<String>> groupAnagrams(String[] strs) {
        Map<String, List<String>> map = new HashMap<>();
        for (String s : strs) {
            char[] chars = s.toCharArray();
            Arrays.sort(chars);                // 排序后作为 key
            String key = new String(chars);
            map.computeIfAbsent(key, k -> new ArrayList<>()).add(s);
        }
        return new ArrayList<>(map.values());
    }

    // 方法二：计数法 — O(n·k)，省掉 log k
    public List<List<String>> groupAnagramsCount(String[] strs) {
        Map<String, List<String>> map = new HashMap<>();
        for (String s : strs) {
            int[] count = new int[26];
            for (char c : s.toCharArray()) {
                count[c - 'a']++;
            }
            // 固定 26 位定长 key，避免碰撞
            StringBuilder sb = new StringBuilder(52);
            for (int i = 0; i < 26; i++) {
                sb.append(count[i]).append('#'); // 用 '#' 分隔防止 "1,23" 与 "12,3" 冲突
            }
            String key = sb.toString();
            map.computeIfAbsent(key, k -> new ArrayList<>()).add(s);
        }
        return new ArrayList<>(map.values());
    }

    public static void main(String[] args) {
        Solution sol = new Solution();
        String[] strs = {"eat","tea","tan","ate","nat","bat"};
        System.out.println(sol.groupAnagrams(strs));
        // 输出: [[eat, tea, ate], [tan, nat], [bat]]（顺序可能不同）
    }
}
